    /**
     * Tests creating a new Campaign.
     *
     * @return    Campaign
     */
    public Campaign testCreate() throws Throwable {
    Campaign entity = null;

    LOGGER.info( "CampaignTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Campaign");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Campaign" );

    try {
        entity = service.createCampaign( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getCampaignId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Campaign with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

