    /**
     * Tests getting all Campaigns.
     *
     * @return    Collection
     */
    public List<Campaign> testGetAll() throws Throwable {
    LOGGER.info( "CampaignTest:testGetAll() - Retrieving Collection of Campaigns:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Campaign : " );
    List<Campaign> collection  = null;

    try {
        // call the static get method on the CampaignService
        collection = service.getAllCampaign();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Campaign currEntity  = null;
            Iterator<Campaign> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getCampaignId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

